export function makeNull() {
  return { type: 'null' };
}

export function makeBool(value) {
  return { type: 'bool', value: value === true };
}

export function makeInt(value) {
  return { type: 'int', value };
}

export function makeFloat(value, negativeZero = false) {
  return { type: 'float', value, negativeZero: negativeZero === true };
}

export function makeString(value) {
  return { type: 'str', value };
}

export function makeList(items) {
  return { type: 'list', items };
}

export function makeTuple(items) {
  return { type: 'tuple', items };
}

export function makeDict(entries) {
  return { type: 'dict', entries };
}

export function makeSet(items) {
  return { type: 'set', items };
}

export function isScalar(node) {
  return (
    node.type === 'null' ||
    node.type === 'bool' ||
    node.type === 'int' ||
    node.type === 'float' ||
    node.type === 'str'
  );
}

export function isSequence(node) {
  return node.type === 'list' || node.type === 'tuple';
}

export function isMapping(node) {
  return node.type === 'dict' || node.type === 'set';
}

export function isCollection(node) {
  return isSequence(node) || isMapping(node);
}

export function isNumeric(node) {
  return node.type === 'bool' || node.type === 'int' || node.type === 'float';
}

export function numericToNumber(node) {
  if (node.type === 'bool') {
    return node.value ? 1 : 0;
  }
  if (node.type === 'int') {
    return Number(node.value);
  }
  return node.value;
}

export function numericToBigInt(node) {
  if (node.type === 'bool') {
    return node.value ? 1n : 0n;
  }
  return node.value;
}

